import{GYM4_GAMEPLAY,GYM4_GAMEPLAY_REVISION}from'./fixed-registration.mjs';
import{GYM4_WARPS}from'./fixed-warp-registration.mjs';
import{gym4ObservationMessage}from'./presentation.mjs';
const inRows=(rows,foot)=>rows.some(([y,lo,hi])=>foot[1]===y&&foot[0]>=lo&&foot[0]<hi);
const labels=Object.freeze({'puzzle:4:step:1':'벽그림의 방문 안내 확인','puzzle:4':'책장 옆 방문 확인','trainer:GYM_04_SUB_01':'생태해설 수습원','trainer:GYM_04_SUB_02':'도시환경 조사보조','trainer:NPC_GYM_04_JINSEONG':'진성'});
// Private factory integration adapter; no RAF, input listeners, storage or canonical relocation.
export function createGym4Scene({location,registry,provider,sessionEpoch,onSuccessfulPixel=null}){
 if(registry.validate(location)||location.mapId!=='world:gym:4'||!Number.isSafeInteger(sessionEpoch)||sessionEpoch<1)throw Error('GYM4_REGISTERED_INITIAL_REQUIRED');
 const walker=provider.createWalker(location),lifecycle=new AbortController();let pose=structuredClone(location),world=null,disposed=false,locked=false,acting=false;
 const read=()=>{const n=walker.read();return{...structuredClone(pose),foot:[...n.foot],facing:n.facing}};
 const match=()=>{const n=read();return GYM4_GAMEPLAY.find(r=>r.facing===n.facing&&inRows(r.states[n.state].rows,n.foot))};
 const api={mapId:'world:gym:4',sessionEpoch,get disposed(){return disposed},get world(){return world},get locked(){return locked},set locked(v){locked=v===true;walker.setLocked(locked)},bindWorld(w){if(world&&world!==w)throw Error('WORLD_REPLACEMENT_REQUIRES_NEW_OWNER');if(registry.validateRuntime(read(),w.snapshot()))throw Error('GYM4_RUNTIME_STATE_MISMATCH');world=w},getLocation:read,
 readNative(){if(disposed||locked||world?.field?.menu!=null)return null;const n=read();return{version:1,sceneId:n.sceneId,mapId:n.mapId,revision:n.mapRevision,imageSHA:n.imageSHA,maskSHA:n.maskSHA,foot:[...n.foot],facing:n.facing,phase:'field',sessionEpoch}},readGym4Native(){const n=api.readNative();return n?{...n,gameplayRevision:GYM4_GAMEPLAY_REVISION,state:pose.state}:null},getGym4Signal:()=>lifecycle.signal,
 prepareCommittedLocation(next){if(disposed||registry.validate(next))throw Error('GYM4_PREPARE_LOCATION_REJECTED');const before=read();for(const k of['mapId','sceneId','retainedHubState','facing'])if(next[k]!==before[k])throw Error('GYM4_PREPARE_OWNER_DRIFT');if(next.foot.some((v,i)=>v!==before.foot[i])||JSON.stringify(next.movement)!==JSON.stringify(before.movement)||!provider.safe(next.state,next.foot))throw Error('GYM4_PREPARE_FOOT_DRIFT');const captured=structuredClone(next);let applied=false;return()=>{if(applied)return;if(disposed||JSON.stringify(read())!==JSON.stringify(before))throw Error('GYM4_APPLY_OWNER_DRIFT');if(registry.validateRuntime(captured,world.snapshot()))throw Error('GYM4_APPLY_RUNTIME_MISMATCH');walker.adopt(captured);pose=captured;applied=true}},
 stop(){walker.stop()},releaseAction(){},frame(dt,dir){if(disposed||locked||acting||world?.busy||world?.inputLocked||world?.field?.menu!=null){walker.stop();return false}return walker.frame(dt,dir,onSuccessfulPixel)>0},draw(ctx,clock){if(disposed)return false;return provider.draw(ctx,walker.read(),clock)},
 proximityHint(){if(disposed)return '';const n=read(),r=GYM4_GAMEPLAY.find(r=>inRows(r.states[n.state].rows,n.foot));if(r)return labels[r.pointId]+' · '+(r.facing===n.facing?'조사':r.facing==='right'?'오른쪽을 보고 조사':'위를 보고 조사');const exit=GYM4_WARPS[1];return inRows(exit.approach.rows,n.foot)?'고현으로 돌아가기 · 아래를 보고 조사':'생활 체육관 · 방문 안내와 원래 대결 · 개발 메모리 전용'},
 async inspect(execution){if(disposed||locked||acting||!world||world.busy||world.inputLocked)throw Error('INPUT_LOCKED');const originalWorld=world,r=match();if(r){acting=true;walker.stop();try{const result=await world.interactNativeGym4(r.pointId,{type:r.kind});if(disposed||world!==originalWorld)throw Error('GYM4_ACTION_OWNER_CHANGED');const notice=r.kind==='trainer'&&result?.alreadyDefeated===true&&typeof result.message==='string'?result.message:gym4ObservationMessage(r.pointId,result,world.snapshot());return{...result,gameplayHandled:true,...(notice?{gameplayNotice:notice}:{})}}finally{acting=false}}const n=read(),exit=GYM4_WARPS[1];if(n.facing===exit.facing&&inRows(exit.approach.rows,n.foot)){if(typeof execution!=='function')throw Error('TRUSTED_EXECUTION_REQUIRED');return execution(exit.pointId)}return{executed:false,reason:'NO_SELECTED_PORT_IN_REACH'}},
 dispose(){if(disposed)return;disposed=true;lifecycle.abort();walker.dispose();world=null}};return api;
}
